import { useState } from 'react';
import { JxTagInput } from '@jinx-ui/react';

type ArticleTagPickerProps = {
  label?: string;
  placeholder?: string;
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
};

export default function ArticleTagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  value,
  defaultValue = [],
  onChange,
}: ArticleTagPickerProps) {
  const [uncontrolledTags, setUncontrolledTags] = useState<string[]>(defaultValue);
  const tags = value ?? uncontrolledTags;

  const handleValueChange = (next: string[]) => {
    const unique = next.filter((tag, index) => next.indexOf(tag) === index);
    if (value === undefined) {
      setUncontrolledTags(unique);
    }
    onChange?.(unique);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', fontFamily: 'var(--jx-font-sans)' }}>
      <span>{label}</span>
      <JxTagInput
        ariaLabel={label}
        placeholder={placeholder}
        value={tags}
        onValueChange={handleValueChange}
      />
    </div>
  );
}

